-- PostgreSQL 15+; fictional assets only.
CREATE SCHEMA IF NOT EXISTS kcca_demo;
CREATE TABLE IF NOT EXISTS kcca_demo.assets(asset_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,asset_ref TEXT NOT NULL UNIQUE,asset_type TEXT NOT NULL CHECK(asset_type IN('road_segment','drainage','streetlight','public_building','market_facility','waste_point','other')),area_code TEXT NOT NULL,display_label TEXT NOT NULL,condition_state TEXT NOT NULL DEFAULT 'unknown' CHECK(condition_state IN('good','fair','poor','critical','unknown')),is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS kcca_demo.inspections(inspection_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,inspection_ref TEXT NOT NULL UNIQUE,asset_id BIGINT NOT NULL REFERENCES kcca_demo.assets(asset_id) ON DELETE RESTRICT,inspected_at TIMESTAMPTZ NOT NULL,condition_state TEXT NOT NULL CHECK(condition_state IN('good','fair','poor','critical')),priority SMALLINT NOT NULL CHECK(priority BETWEEN 1 AND 5),inspector_ref TEXT NOT NULL,summary TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS kcca_demo.work_orders(work_order_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,work_ref TEXT NOT NULL UNIQUE,asset_id BIGINT NOT NULL REFERENCES kcca_demo.assets(asset_id) ON DELETE RESTRICT,inspection_id BIGINT REFERENCES kcca_demo.inspections(inspection_id) ON DELETE RESTRICT,work_type TEXT NOT NULL CHECK(work_type IN('repair','cleaning','replacement','inspection','other')),summary TEXT NOT NULL,priority SMALLINT NOT NULL CHECK(priority BETWEEN 1 AND 5),estimated_cost_ugx NUMERIC(18,2) NOT NULL CHECK(estimated_cost_ugx>=0),due_date DATE,status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN('planned','in_progress','blocked','completed','cancelled')),completed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(status<>'completed' OR completed_at IS NOT NULL));
CREATE TABLE IF NOT EXISTS kcca_demo.work_events(event_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,work_order_id BIGINT NOT NULL REFERENCES kcca_demo.work_orders(work_order_id) ON DELETE RESTRICT,previous_status TEXT,new_status TEXT NOT NULL CHECK(new_status IN('planned','in_progress','blocked','completed','cancelled')),note TEXT NOT NULL,actor_ref TEXT NOT NULL,happened_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_kcca_assets_area_type ON kcca_demo.assets(area_code,asset_type) WHERE is_active;
CREATE INDEX IF NOT EXISTS ix_kcca_work_queue ON kcca_demo.work_orders(status,priority DESC,due_date);
CREATE INDEX IF NOT EXISTS ix_kcca_inspection_asset_time ON kcca_demo.inspections(asset_id,inspected_at DESC);